    "; 0 = off. 0 .. 50.\n"
    "head_sway_test = 0\n"
    "; End the game when a frame has been stuck this many seconds (the log says\n"
    "; where). For unattended tests. 0 = never. 0 .. 600.\n"
    "hang_exit_seconds = 0\n"
    "; live: reload psyvr_logic.dll while the game runs when it is rebuilt (checked\n"
    "; every 30 frames); for development. 0 = loaded once.\n"
    "hot_reload = 0\n"
    "; start-up only: a named pipe (\\.\\pipe\\psyvr) takes test commands (ping,\n"
    "; status, shot, drawlog, set, ...; tools\\drive.ps1 Psy-Cmd) while the game runs. For\n"
    "; development. 0 = off.\n"
    "control_pipe = 0\n";
